      margin: 18px 0 0;
      color: var(--success);
      font-weight: 700;
      text-align: center;
    }
  </style>
</head>
<body>
  <main class="support-shell">
    <section class="contact-card" aria-labelledby="support-title">
      <div class="contact-content">
        <p class="eyebrow">Support request</p>
        <h1 id="support-title">How can we help?</h1>
        <p class="intro">Send our support team your contact details and we will get back to you as soon as possible.</p>

        <form id="supportForm" novalidate>
          <div id="formRoot"></div>
          <button class="submit-button" type="submit">Submit support request</button>
          <p class="success-message" id="successMessage" role="status" aria-live="polite"></p>
        </form>
      </div>
    </section>
  </main>

  <script>
    const fields = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        placeholder: "Jordan Lee",
        required: true,
        validate(value) {
          return value.trim() ? "" : "Full name is required.";
        }
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        placeholder: "jordan@example.com",
        required: true,
        validate(value) {
          if (!value.trim()) return "Email address is required.";
          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
            ? ""
            : "Enter a valid email address.";
        }
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        placeholder: "+1 555 123 4567",
        required: false,
        optionalLabel: "Optional",
        helperText: "Expected format: include an area code, such as +1 555 123 4567 or (555) 123-4567.",
        validate(value) {
          if (!value.trim()) return "";
          return /^\+?[0-9\s().-]{7,20}$/.test(value.trim())
            ? ""
            : "Enter a valid phone number.";
        }
      }
    ];

    const formState = fields.reduce((state, field) => {
      state[field.id] = "";
      return state;
    }, {});

    const touchedState = {};
    const formRoot = document.querySelector("#formRoot");
    const supportForm = document.querySelector("#supportForm");
    const successMessage = document.querySelector("#successMessage");

    function FieldComponent(field) {
      const wrapper = document.createElement("div");
      const errorId = `${field.id}Error`;
      const helperId = field.helperText ? `${field.id}Helper` : "";

      wrapper.className = "form-field";
      wrapper.innerHTML = `
        <label for="${field.id}">
          <span>${field.label}${field.required ? " *" : ""}</span>
          ${field.optionalLabel ? `<span class="optional">${field.optionalLabel}</span>` : ""}
        </label>
        <input
          id="${field.id}"
          name="${field.id}"
          type="${field.type}"
          autocomplete="${field.autocomplete}"
          placeholder="${field.placeholder}"
          ${field.required ? "required" : ""}
          aria-invalid="false"
          aria-describedby="${[helperId, errorId].filter(Boolean).join(" ")}"
        >
        ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
        <p class="validation-message" id="${errorId}" aria-live="polite"></p>
      `;

      const input = wrapper.querySelector("input");
      input.addEventListener("input", (event) => {
        formState[field.id] = event.target.value;
        if (touchedState[field.id]) validateField(field);
        successMessage.textContent = "";
      });
      input.addEventListener("blur", () => {
        touchedState[field.id] = true;
        validateField(field);
      });

      return wrapper;
    }

    function ContactFormComponent() {
      fields.forEach((field) => {
        formRoot.appendChild(FieldComponent(field));
      });
    }

    function validateField(field) {
      const input = document.querySelector(`#${field.id}`);
      const error = document.querySelector(`#${field.id}Error`);
      const message = field.validate(formState[field.id]);

      input.setAttribute("aria-invalid", message ? "true" : "false");
      error.textContent = message;
      return !message;
    }

    function validateForm() {
      let isValid = true;

      fields.forEach((field) => {
        touchedState[field.id] = true;
        if (!validateField(field)) isValid = false;
      });

      return isValid;
    }

    ContactFormComponent();

    supportForm.addEventListener("submit", (event) => {
      event.preventDefault();
      successMessage.textContent = "";

      if (!validateForm()) return;

      successMessage.textContent = "Thanks. Your support request is ready to send.";
      supportForm.reset();
      fields.forEach((field) => {
        formState[field.id] = "";
        touchedState[field.id] = false;
      });
    });
  </script>
</body>
</html>
