    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 32px 18px;
      background:
        radial-gradient(circle at top left, rgba(56, 189, 248, 0.18), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(99, 102, 241, 0.2), transparent 32rem),
        linear-gradient(135deg, #050711 0%, var(--bg) 55%, #0f172a 100%);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .support-shell {
      width: min(100%, 540px);
    }

    .contact-card {
      position: relative;
      overflow: hidden;
      padding: clamp(28px, 5vw, 42px);
      border: 1px solid var(--panel-border);
      border-radius: 28px;
      background: linear-gradient(180deg, rgba(30, 41, 59, 0.92), var(--panel));
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .contact-card::before {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      background: linear-gradient(120deg, rgba(255, 255, 255, 0.12), transparent 38%);
      opacity: 0.55;
    }

    .contact-content {
      position: relative;
      z-index: 1;
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 3.2rem);
      line-height: 1;
      letter-spacing: -0.05em;
    }

    .intro {
      margin: 16px 0 30px;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    .form-field {
      margin-bottom: 20px;
    }

    label {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 8px;
      color: #dbeafe;
      font-size: 0.94rem;
      font-weight: 700;
    }

    .optional {
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 600;
    }

    input {
      width: 100%;
      min-height: 52px;
      border: 1px solid var(--input-border);
      border-radius: 15px;
      outline: none;
      padding: 0 16px;
      background: var(--input);
      color: var(--text);
      font: inherit;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: rgba(56, 189, 248, 0.85);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.16);
